class ConnectGame:
    def __init__(self, board):
        self.board = [row.split() for row in board.strip().splitlines() if row.strip()]
        self.rows = len(self.board)
        self.cols = len(self.board[0]) if self.board else 0

    def get_winner(self):
        if self._connects("O", "top"):
            return "O"
        if self._connects("X", "left"):
            return "X"
        return ""

    def _connects(self, player, side):
        if self.rows == 0:
            return False
        if side == "top":
            # Player O connects the top edge to the bottom edge.
            start = [(0, c) for c in range(self.cols) if self.board[0][c] == player]
            reached = lambda r, c: r == self.rows - 1
        else:
            # Player X connects the left edge to the right edge.
            start = [(r, 0) for r in range(self.rows) if self.board[r][0] == player]
            reached = lambda r, c: c == self.cols - 1

        visited = set(start)
        stack = list(start)
        while stack:
            r, c = stack.pop()
            if reached(r, c):
                return True
            for dr, dc in ((0, -1), (0, 1), (-1, -1), (-1, 0), (1, 0), (1, 1)):
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < self.rows
                    and 0 <= nc < self.cols
                    and (nr, nc) not in visited
                    and self.board[nr][nc] == player
                ):
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return False

